import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { Panel, PanelHeader, PanelTitle, PanelTitleSup } from "@/components/panel";
import { PostSearch } from "@/components/post-search";
import { getPublishedPosts } from "@/lib/blog";
import { serializeJsonLd } from "@/lib/json-ld";
import { site } from "@/lib/site";

/**
 * With nothing published the route 404s, so it must not advertise itself as a
 * Blog — naming a page the Visitor cannot reach is a lie told by the tab.
 */
export function generateMetadata(): Metadata {
  if (getPublishedPosts().length === 0) return { title: "Nothing lives here" };
  return {
    title: "Blog",
    alternates: { canonical: `${site.url}/blog` },
  };
}

export default function BlogPage() {
  // Nothing empty is ever shown to a Visitor (CONTEXT.md → Blog / Post).
  const posts = getPublishedPosts();
  if (posts.length === 0) notFound();

  // The body is the one thing a row never draws, and the rows are drawn in the
  // browser here — so it is dropped before the list crosses over rather than
  // shipped down and ignored.
  const summaries = posts.map(({ content: _content, ...summary }) => summary);

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "Blog",
    "@id": `${site.url}/blog`,
    name: "Blog",
    url: `${site.url}/blog`,
    author: { "@type": "Person", name: site.name, url: site.url },
    blogPost: posts.map((post) => ({
      "@type": "BlogPosting",
      "@id": `${site.url}/blog/${post.slug}`,
      headline: post.title,
      description: post.summary,
      url: `${site.url}/blog/${post.slug}`,
      datePublished: post.publishedAt,
    })),
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: serializeJsonLd(jsonLd) }}
      />

      {/* One panel, not a heading floating above a list: the index is a single
          thing on the page, and the site draws single things inside rails.
          There is no tagline under the title — the reference needs one because
          its heading *is* the tagline; ours says the word the nav promised and
          then gets out of the way of the posts. */}
      <Panel id="blog">
        <PanelHeader>
          <PanelTitle as="h1">
            Blog
            <PanelTitleSup className="tabular-nums">
              {posts.length}
            </PanelTitleSup>
          </PanelTitle>
        </PanelHeader>

        <PostSearch posts={summaries} />
      </Panel>
    </>
  );
}

import { describe, expect, test } from "bun:test";
import { formatPostDate, searchPosts, type PostSummary } from "@/lib/posts";

const post = (over: Partial<PostSummary>): PostSummary => ({
  slug: "a-post",
  title: "A Post",
  summary: "A sentence about it.",
  publishedAt: "2026-01-01",
  readingTimeMinutes: 3,
  ...over,
});

const POSTS: PostSummary[] = [
  post({
    slug: "gpt-5-6-review",
    title: "GPT-5.6 Review",
    summary: "Notes on burning three and a half billion tokens.",
    tags: ["models"],
  }),
  post({
    slug: "repro-harness",
    title: "Building a repro harness",
    summary: "Coding agents need a way to fail the same way twice.",
    tags: ["tooling", "agents"],
  }),
];

describe("searchPosts", () => {
  test("an empty query is not a filter", () => {
    expect(searchPosts(POSTS, "")).toHaveLength(2);
    expect(searchPosts(POSTS, "   ")).toHaveLength(2);
  });

  test("returns a copy, so a caller cannot sort the source out from under it", () => {
    expect(searchPosts(POSTS, "")).not.toBe(POSTS);
  });

  test("matches the title regardless of case", () => {
    expect(searchPosts(POSTS, "gpt").map((p) => p.slug)).toEqual([
      "gpt-5-6-review",
    ]);
  });

  test("matches the summary, not just the title", () => {
    expect(searchPosts(POSTS, "billion").map((p) => p.slug)).toEqual([
      "gpt-5-6-review",
    ]);
  });

  test("matches a tag, which is the word a reader is most likely to type", () => {
    expect(searchPosts(POSTS, "tooling").map((p) => p.slug)).toEqual([
      "repro-harness",
    ]);
  });

  test("ignores spaces on both sides, so a fast typist still lands", () => {
    expect(searchPosts(POSTS, "codingagents").map((p) => p.slug)).toEqual([
      "repro-harness",
    ]);
    expect(searchPosts(POSTS, "  repro harness ").map((p) => p.slug)).toEqual([
      "repro-harness",
    ]);
  });

  test("no match is an empty list, never the whole list", () => {
    expect(searchPosts(POSTS, "kubernetes")).toEqual([]);
  });
});

describe("formatPostDate", () => {
  test("a date-only string is not dragged across a timezone", () => {
    // `2026-01-01` parsed as UTC and printed in a western zone is 31 December.
    // The formatter reads it as local midnight so the day printed is the day
    // written.
    expect(formatPostDate("2026-01-01")).toBe("January 1, 2026");
  });
});

