"use client";

import { CloseIcon, SearchIcon } from "@/components/icons";

/**
 * The filter above a list. One field, used by the blog index and the projects
 * index, so the two pages type the same way — the second search box a Visitor
 * meets should teach them nothing new.
 *
 * It owns no state: the list it filters does, because the list is the thing
 * that has to re-render. See `PostSearch` and `ProjectSearch`.
 */
export function SearchField({
  value,
  onChange,
  label,
  placeholder,
}: {
  value: string;
  onChange: (value: string) => void;
  label: string;
  placeholder: string;
}) {
  return (
    <div className="screen-line-bottom p-2">
      <div className="relative flex items-center">
        <SearchIcon
          aria-hidden
          className="pointer-events-none absolute left-3 size-4 text-muted-foreground"
        />
        <input
          type="search"
          value={value}
          onChange={(event) => onChange(event.target.value)}
          onKeyDown={(event) => {
            // Escape empties the field before it does anything else — the same
            // key the palette closes with, doing the same job here.
            if (event.key === "Escape" && value) {
              event.preventDefault();
              onChange("");
            }
          }}
          placeholder={placeholder}
          aria-label={label}
          autoComplete="off"
          spellCheck={false}
          /* 16px on a phone: anything smaller and iOS zooms the page on focus,
             which lands the Visitor somewhere they did not ask to be. */
          className="h-9 w-full rounded-lg border border-border bg-transparent pr-9 pl-9 text-base text-foreground placeholder:text-muted-foreground sm:text-sm dark:bg-input/30"
        />
        {value ? (
          <button
            type="button"
            onClick={() => onChange("")}
            aria-label="Clear search"
            className="absolute right-1.5 flex size-6 items-center justify-center rounded-sm text-muted-foreground transition-colors hover:text-foreground"
          >
            <CloseIcon className="size-4" />
          </button>
        ) : null}
      </div>
    </div>
  );
}

/**
 * What a filter did, for someone who cannot see the list change shape. The
 * count is the whole message: a screen reader announcing every matching title
 * on every keystroke is worse than silence.
 */
export function SearchStatus({
  count,
  noun,
}: {
  count: number;
  noun: string;
}) {
  return (
    <p role="status" className="sr-only">
      {count === 1 ? `1 ${noun}` : `${count} ${noun}s`}
    </p>
  );
}

"use client";

import { useMemo, useState } from "react";
import { PostItem } from "@/components/post-item";
import { SearchField, SearchStatus } from "@/components/search-field";
import { searchPosts, type PostSummary } from "@/lib/posts";

/**
 * The index, with a filter over it.
 *
 * The reference keeps its query in the URL, which buys a shareable search and
 * costs a query-state dependency, a Suspense boundary and a router write on
 * every keystroke. A filter over a list this size is a glance, not a
 * destination — nobody sends a friend a link to a filtered blog index — so the
 * query lives in the component and the URL stays the address of the page.
 *
 * The list is not virtualised and does not need to be: it is filtering an
 * array that was already sent, in memory, with no request behind it.
 */
export function PostSearch({ posts }: { posts: PostSummary[] }) {
  const [query, setQuery] = useState("");
  const shown = useMemo(() => searchPosts(posts, query), [posts, query]);

  return (
    <>
      <SearchField
        value={query}
        onChange={setQuery}
        label="Search posts"
        placeholder="Search posts…"
      />
      <SearchStatus count={shown.length} noun="post" />

      {shown.length > 0 ? (
        <ul>
          {shown.map((post) => (
            <PostItem key={post.slug} post={post} headingAs="h2" />
          ))}
        </ul>
      ) : (
        <p className="p-4 font-mono text-sm text-muted-foreground">
          No posts match “{query}”.
        </p>
      )}
    </>
  );
}

"use client";

import { useMemo, useState } from "react";
import { ProjectRow } from "@/components/project-row";
import { SearchField, SearchStatus } from "@/components/search-field";
import { searchProjects, type Project } from "@/lib/projects";

/**
 * The whole list of projects, with the same filter the blog index has.
 *
 * Eight rows do not strictly need searching. The field is here because the two
 * indexes are the same kind of page and should not behave differently — and
 * because the thing a Visitor actually arrives wanting is usually a language
 * or a kind ("rust", "cli"), which is a word to type rather than a row to find
 * by eye.
 */
export function ProjectSearch({ projects }: { projects: Project[] }) {
  const [query, setQuery] = useState("");
  const shown = useMemo(
    () => searchProjects(projects, query),
    [projects, query],
  );

  return (
    <>
      <SearchField
        value={query}
        onChange={setQuery}
        label="Search projects"
        placeholder="Search projects…"
      />
      <SearchStatus count={shown.length} noun="project" />

      {shown.length > 0 ? (
        <ul>
          {shown.map((project) => (
            <ProjectRow key={project.name} project={project} />
          ))}
        </ul>
      ) : (
        <p className="p-4 font-mono text-sm text-muted-foreground">
          No projects match “{query}”.
        </p>
      )}
    </>
  );
}

