3. Files and Code Sections:

   **`lib/slug.ts`** (NEW) — one `slugify` shared by the MDX renderer and the TOC so heading ids and anchors cannot drift:
   ```ts
   export function slugify(str: unknown): string {
     return String(str)
       .toLowerCase()
       .trim()
       .replace(/\s+/g, "-")
       .replace(/&/g, "-and-")
       .replace(/[^\w-]+/g, "")
       .replace(/--+/g, "-");
   }
   ```

   **`components/mdx.tsx`** — local `slugify` deleted; now `import { slugify } from "@/lib/slug";` at line 8, used at line 61.

   **`lib/toc.ts`** (NEW) — parses `##`/`###` out of MDX source, skipping fenced blocks:
   ```ts
   export type TocEntry = { depth: 2 | 3; text: string; slug: string };
   const FENCE = /^\s{0,3}(`{3,}|~{3,})/;
   const HEADING = /^(#{2,3})\s+(.+?)\s*#*\s*$/;
   function plain(text: string): string {
     return text
       .replace(/!?\[([^\]]*)\]\([^)]*\)/g, "$1")
       .replace(/[`*_]/g, "")
       .trim();
   }
   export function tableOfContents(source: string): TocEntry[] { /* fence tracking by first char; push {depth, text, slug: slugify(text)} */ }
   ```

   **`lib/toc.test.ts`** (NEW) — 10 tests: order, no headings, ignores h1/h4, fence skipping, fence closes only on its own char, strips code/emphasis/link syntax, trailing hashes, `##hashtag` needs a space, slug equals `slugify(...)`.

   **`lib/posts.ts`** — now begins `import { filterByQuery } from "@/lib/search";`. `searchPosts` rewritten onto the shared matcher; `findNeighbours` and `postMarkdown` appended:
   ```ts
   export function searchPosts<
     T extends Pick<PostSummary, "title" | "summary" | "tags">,
   >(posts: readonly T[], query: string): T[] {
     return filterByQuery(posts, query, (post) => [
       post.title,
       post.summary,
       ...(post.tags ?? []),
     ]);
   }

   export function findNeighbours<T extends { slug: string }>(
     posts: readonly T[],
     slug: string,
   ): { newer: T | null; older: T | null } {
     const index = posts.findIndex((post) => post.slug === slug);
     if (index === -1) return { newer: null, older: null };
     return { newer: posts[index - 1] ?? null, older: posts[index + 1] ?? null };
   }

   export function postMarkdown(
     post: Pick<PostSummary, "title" | "summary" | "publishedAt">,
     url: string,
     content: string,
   ): string {
     return (
       [
         `# ${post.title}`,
         `> ${post.summary}`,
         `${formatPostDate(post.publishedAt)} · ${url}`,
         content.trim(),
       ].join("\n\n") + "\n"
     );
   }
   ```

   **`lib/search.ts`** (NEW) — one matcher for every filtered list:
   ```ts
   const normalize = (text: string) =>
     text.toLowerCase().replaceAll(" ", "").replaceAll("-", "");

   export function filterByQuery<T>(
     items: readonly T[],
     query: string,
     terms: (item: T) => readonly (string | number | undefined)[],
   ): T[] {
     const needle = normalize(query.trim());
     if (!needle) return [...items];
     return items.filter((item) =>
       normalize(terms(item).filter((term) => term !== undefined).join(" ")).includes(needle),
     );
   }
   ```

